struct CharList {
  static constexpr MsgId kId = MsgId::CharList;
  static constexpr std::uint8_t kChannel = 0;
  static constexpr Direction kDirection = Direction::ServerToClient;
  static constexpr const char* kName = "CharList";
  std::uint8_t max_characters{};
  std::vector<CharSummary> characters;
  void encode(Writer& w) const {
    w.u8(max_characters);
    { const std::size_t count = std::min<std::size_t>(characters.size(), 16);
      w.u16(static_cast<std::uint16_t>(count));
      for (std::size_t i = 0; i < count; ++i) {
        characters[i].encode(w);
      }
    }
  }
  bool decode(Reader& r) {
    if (!r.u8(max_characters)) return false;
    { std::uint16_t count = 0;
      if (!r.u16(count) || count > 16) return r.fail();
      characters.clear();
      characters.reserve(count);
      for (std::uint16_t i = 0; i < count; ++i) {
        CharSummary v;
        if (!v.decode(r)) return false;
        characters.push_back(std::move(v));
      }
    }
    return true;
  }
};

