  std::string name;
  std::uint64_t coin{};
  std::vector<LootEntry> items;
  bool master{};
  std::vector<std::string> party;
  void encode(Writer& w) const {
    w.u32(corpse_id);
    w.str(name, 64);
    w.u64(coin);
    { const std::size_t count = std::min<std::size_t>(items.size(), 32);
      w.u16(static_cast<std::uint16_t>(count));
      for (std::size_t i = 0; i < count; ++i) {
        items[i].encode(w);
      }
    }
    w.boolean(master);
    { const std::size_t count = std::min<std::size_t>(party.size(), 72);
      w.u16(static_cast<std::uint16_t>(count));
      for (std::size_t i = 0; i < count; ++i) {
        w.str(party[i], 15);
      }
    }
  }
  bool decode(Reader& r) {
    if (!r.u32(corpse_id)) return false;
    if (!r.str(name, 64)) return false;
    if (!r.u64(coin)) return false;
    { std::uint16_t count = 0;
      if (!r.u16(count) || count > 32) return r.fail();
      items.clear();
      items.reserve(count);
      for (std::uint16_t i = 0; i < count; ++i) {
        LootEntry v;
        if (!v.decode(r)) return false;
        items.push_back(std::move(v));
      }
    }
    if (!r.boolean(master)) return false;
    { std::uint16_t count = 0;
      if (!r.u16(count) || count > 72) return r.fail();
      party.clear();
      party.reserve(count);
      for (std::uint16_t i = 0; i < count; ++i) {
        std::string v;
        if (!r.str(v, 15)) return false;
        party.push_back(std::move(v));
      }
    }
    return true;
  }
